package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: each date is blank or yyyy-MM-dd. */
public class ValidateHold {
    public void validate(@RequestBody HoldRequest request, Out<Hold> hold) throws InvalidPersonException {
        LocalDate from = date(request == null ? null : request.from(), "from");
        LocalDate to = date(request == null ? null : request.to(), "to");
        hold.set(new Hold(from, to, request == null || request.by() == null ? "" : request.by().trim()));
    }

    private static LocalDate date(String value, String which) throws InvalidPersonException {
        String text = value == null ? "" : value.trim();
        if (text.isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new InvalidPersonException("The hold's " + which + "-date must be yyyy-MM-dd");
        }
    }
}
    onSuccess: () => {
      setFrom('');
      setTo('');
      return queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
    onSettled: submit.end,
  });

  return (
    <>
      <td data-testid="person-hold">{person.held ? 'yes' : 'no'}</td>
      <td>
        {(person.holds ?? []).map((h, i) => (
          <div key={i} data-testid="person-hold-line">
            {h.from} – {h.to ?? ''}
          </div>
        ))}
        <input
          data-testid="person-hold-from"
          placeholder="from yyyy-MM-dd"
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            hold.reset();
          }}
        />{' '}
        <input
          data-testid="person-hold-to"
          placeholder="to yyyy-MM-dd"
          value={to}
          onChange={(e) => {
            setTo(e.target.value);
            hold.reset();
          }}
        />{' '}
        <button
          type="button"
          data-testid="person-hold-toggle"
          disabled={hold.isPending}
          onClick={() => {
            if (!submit.begin()) return;
            rowAction.take();
            hold.reset();
            hold.mutate({ from: from.trim(), to: to.trim() });
          }}
        >
          Hold
        </button>
        {hold.isError && rowAction.isLatest && <span data-testid="person-error"> Could not hold this person.</span>}
      </td>
    </>

